* { box-sizing: border-box; }

body {
     margin: 0;
     min-height: 100vh;
     padding: 36px 16px;
     font-family: Arial, "Segoe UI", sans-serif;
     background: linear-gradient(160deg, #eef2ff, #f8fafc);
}

.khung-bai {
     max-width: 1000px;
     margin: 0 auto;
}

.khung-bai h1 {
     text-align: center;
     font-size: 28px;
     margin: 0 0 6px;
     color: #1e293b;
}

.mo-ta {
     text-align: center;
     color: #64748b;
     margin: 0 0 34px;

    font-size: 15px;
}

.luoi-gia {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 20px;
    align-items: stretch;
}

.goi {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 14px;
    padding: 26px 22px;
    text-align: center;
    box-shadow: 0 10px 26px rgba(0, 0, 0, 0.06);
    display: flex;
    flex-direction: column;
    transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.goi:hover {
    transform: translateY(-4px);
}

.goi.hot {
    border: 2px solid #4f46e5;
    transform: translateY(-10px);
    box-shadow: 0 18px 40px rgba(79, 70, 229, 0.22);
}

.nhan {
    align-self: center;
    display: inline-block;
    background: #eef2ff;
    color: #4338ca;
    border-radius: 999px;

    padding: 4px 14px;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.5px;
    margin-bottom: 12px;
}

.goi h2 {
    margin: 0 0 6px;
    font-size: 18px;
    color: #334155;
}

.muc-gia {
    font-size: 36px;
    font-weight: 800;
    color: #1e293b;
}

.muc-gia span {
    font-size: 14px;
    font-weight: 400;
    color: #64748b;
}

.goi ul {
    list-style: none;
    padding: 0;
    margin: 16px 0 22px;
    font-size: 14px;
    color: #475569;
    line-height: 2;
    flex: 1;
}

.nut-chon {
    display: block;
    padding: 12px;

     border-radius: 8px;
     text-decoration: none;
     font-weight: 700;
     font-size: 15px;
     background: #f1f5f9;
     color: #334155;
}

.goi.hot .nut-chon {
     background: #4f46e5;
     color: #ffffff;
}

@media (max-width: 768px) {
     .luoi-gia { grid-template-columns: 1fr; }
     .goi.hot { transform: none; }
}
